function fallbackIsEmptyPayload(payload) {
    if (payload === undefined || payload === null) return true;
    if (Buffer.isBuffer(payload) && payload.length === 0) return true;
    if (typeof payload === "string" && payload.trim() === "") return true;
    return false;
}

// Zweck: Leere retained MQTT-Clears herausfiltern, bevor sie den JSON-Parser erreichen.
// flowHelpers kommt normalerweise aus 00_boot. Falls retained Messages frueher eintreffen,
// nutzt dieser Node die lokale Fallback-Pruefung, statt echte Startdaten zu verwerfen.
const flowHelpers = global.get("flowHelpers");
const isEmptyPayload = flowHelpers && typeof flowHelpers.isEmptyPayload === "function"
    ? flowHelpers.isEmptyPayload
    : fallbackIsEmptyPayload;

if (isEmptyPayload(msg.payload)) {
    return null;
}
return msg;

// Zweck: Topic auswerten und als Device-Nachricht einordnen.
// Eingabe:  msg.topic (MQTT-Topicstring)
// Ausgabe:  msg.sh mit Routing-State (scope, topic_type, entity_id, received_at)
//           oder null, wenn das Topic kein Device-Topic ist.
const topicRouter = global.get("topicRouter");
const timeHelpers = global.get("timeHelpers");

// Sicherheitscheck: Wenn die Lib-Helper fehlen (z. B. nach Teil-Redeploy),
// Fehler loggen statt still zu ignorieren.
if (!topicRouter || !timeHelpers) {
    node.error("topicRouter oder timeHelpers fehlen – Boot-Flow prüfen", msg);
    return null;
}

const routed = topicRouter.buildRoutingState(msg.topic, timeHelpers.nowIso());

// Kein Device-Topic oder unbekanntes Format → verwerfen.
if (!routed || routed.scope !== "device") {
    return null;
}

// Sicherstellen, dass immer ein Payload-Objekt vorhanden ist (defensive Initialisierung).
if (msg.payload === undefined || msg.payload === null) {
    msg.payload = {};
}

msg.sh = routed;
return msg;

